#include <algorithm>
#include <array>
#include <fstream>
#include <numeric>
#include <utility>
#include <vector>
struct Edge {int low,high,u,v;};
int main() {
    std::ifstream in("multimoo.in");std::ofstream out("multimoo.out");int n;in >> n;int cells=n*n;
    std::vector<int> color(cells),component(cells,-1),weight,componentColor;
    for(int& value:color) in >> value;
    int largestOne=0;constexpr int dr[4]={-1,1,0,0},dc[4]={0,0,-1,1};
    for(int start=0;start<cells;++start) if(component[start]==-1) {
        int id=static_cast<int>(weight.size()),size=0;std::vector<int> stack{start};component[start]=id;
        while(!stack.empty()) {
            int cell=stack.back();stack.pop_back();++size;int row=cell/n,col=cell%n;
            for(int d=0;d<4;++d){int rr=row+dr[d],cc=col+dc[d];if(rr<0 || rr>=n || cc<0 || cc>=n) continue;int next=rr*n+cc;
                if(component[next]==-1 && color[next]==color[start]){component[next]=id;stack.push_back(next);}}
        }
        weight.push_back(size);componentColor.push_back(color[start]);largestOne=std::max(largestOne,size);
    }
    std::vector<Edge> edges;
    auto add=[&](int u,int v){int a=component[u],b=component[v];if(a==b) return;int x=componentColor[a],y=componentColor[b];edges.push_back({std::min(x,y),std::max(x,y),a,b});};
    for(int row=0;row<n;++row) for(int col=0;col<n;++col){int cell=row*n+col;if(row+1<n) add(cell,cell+n);if(col+1<n) add(cell,cell+1);}
    std::sort(edges.begin(),edges.end(),[](const Edge& a,const Edge& b){return std::pair<int,int>{a.low,a.high}<std::pair<int,int>{b.low,b.high};});
    std::vector<int> parent(weight.size()),size(weight.size()),stamp(weight.size(),0);int epoch=0,largestTwo=0;
    auto find=[&](int u){while(parent[u]!=u){parent[u]=parent[parent[u]];u=parent[u];}return u;};
    for(std::size_t begin=0;begin<edges.size();) {
        std::size_t end=begin+1;while(end<edges.size() && edges[end].low==edges[begin].low && edges[end].high==edges[begin].high) ++end;++epoch;
        for(std::size_t i=begin;i<end;++i) for(int u:{edges[i].u,edges[i].v}) if(stamp[u]!=epoch){stamp[u]=epoch;parent[u]=u;size[u]=weight[u];}
        for(std::size_t i=begin;i<end;++i){int u=find(edges[i].u),v=find(edges[i].v);if(u!=v){if(size[u]<size[v]) std::swap(u,v);parent[v]=u;size[u]+=size[v];}largestTwo=std::max(largestTwo,size[u]);}
        begin=end;
    }
    out << largestOne << '\n' << largestTwo << '\n';
}
